import { cp, mkdir, rm, writeFile } from 'node:fs/promises';

// `dist` is generated by Vite. The root is the primary Pages source; /docs
// remains supported. Both assets folders contain generated files only.
for (const directory of ['.', 'docs']) {
  await mkdir(directory, { recursive: true });
  await rm(`${directory}/assets`, { recursive: true, force: true });
  await cp('dist/assets', `${directory}/assets`, { recursive: true });
  await cp('dist/index.html', `${directory}/index.html`);
  await writeFile(`${directory}/.nojekyll`, '');
}
